# Auto-generated fallback assets for Mini App and Web Interface
import os
import io
import zipfile
import base64
import mimetypes
import logging

log = logging.getLogger(__name__)

ASSETS_ZIP_B64 = ""

def _get_zip():
    data = base64.b64decode(ASSETS_ZIP_B64)
    return zipfile.ZipFile(io.BytesIO(data))

def ensure_assets_on_disk(target_dir: str):
    """Agar target_dir da web fayllar mavjud bo'lmasa, zip dan avtomatik tiklaydi."""
    try:
        app_html = os.path.join(target_dir, 'app.html')
        if not os.path.exists(app_html):
            os.makedirs(target_dir, exist_ok=True)
            zf = _get_zip()
            zf.extractall(target_dir)
            log.info(f"✅ Web assets avtomatik tiklandi: {target_dir}")
    except Exception as e:
        log.error(f"Web assets tiklashda xatolik: {e}")

def get_asset_bytes(filename: str):
    """Xotiradagi zip arxivdan faylni to'g'ridan-to'g'ri o'qib qaytaradi."""
    try:
        clean = filename.lstrip('/')
        zf = _get_zip()
        names = zf.namelist()
        candidates = [clean, f'css/{clean}', f'js/{clean}', f'img/{clean}']
        for c in candidates:
            if c in names:
                mime, _ = mimetypes.guess_type(c)
                if not mime:
                    if c.endswith('.js'): mime = 'application/javascript'
                    elif c.endswith('.css'): mime = 'text/css'
                    elif c.endswith('.html'): mime = 'text/html'
                    else: mime = 'application/octet-stream'
                return zf.read(c), mime
    except Exception as e:
        log.error(f"Assetni o'qishda xatolik: {e}")
    return None, None
